; ---------------------------------------------------------------- music macros
; note byte = length index << 4 | pitch;  pitch 0-B = C..B, C/D = C/C# one octave up, E = tie, F = rest
DEF C_   EQU 0
DEF Cs_  EQU 1
DEF D_   EQU 2
DEF Ds_  EQU 3
DEF E_   EQU 4
DEF F_   EQU 5
DEF Fs_  EQU 6
DEF G_   EQU 7
DEF Gs_  EQU 8
DEF A_   EQU 9
DEF As_  EQU 10
DEF B_   EQU 11
DEF C2_  EQU 12
DEF Cs2_ EQU 13
DEF L96  EQU 0
DEF L72  EQU 1
DEF L48  EQU 2
DEF L32  EQU 3
DEF L36  EQU 4
DEF L24  EQU 5
DEF L16  EQU 6
DEF L18  EQU 7
DEF L12  EQU 8
DEF L8   EQU 9
DEF L6   EQU 10
DEF L4   EQU 11
DEF L3   EQU 12
MACRO note      ; pitch, ticks
    db L\2 << 4 | (\1)
ENDM
MACRO tie       ; ticks
    db L\1 << 4 | $E
ENDM
MACRO rest      ; ticks
    db L\1 << 4 | $F
ENDM
MACRO octave    ; 0-7
    db $D0 | (\1)
ENDM
MACRO oct_up    ; 1-4
    db $D8 | ((\1) - 1)
ENDM
MACRO oct_down  ; 1-4
    db $DC | ((\1) - 1)
ENDM
MACRO vol_fx    ; CH1/CH2
    db $E0
    dw \1
ENDM
MACRO volume    ; CH3: NR32
    db $E0, \1
ENDM
MACRO jump
    db $E1
    dw \1
ENDM
MACRO loop_a    ; --A != 0 -> jump
    db $E2
    dw \1
ENDM
MACRO set_a
    db $E3, \1
ENDM
MACRO pitch_fx
    db $E4
    dw \1
ENDM
MACRO duty      ; CH1/CH2
    db $E5, \1
ENDM
MACRO pan       ; 0 off, 1 right, 2 left, 3 both
    db $E6, \1
ENDM
MACRO tempo     ; CH2
    db $E7, \1
ENDM
MACRO wave      ; CH3
    db $E8
    dw \1
ENDM
MACRO loop_b
    db $E9
    dw \1
ENDM
MACRO set_b
    db $EA, \1
ENDM
MACRO if_a      ; A == n -> jump
    db $EB, \1
    dw \2
ENDM
MACRO doubletime ; FFA CH2 only: sets a flag the tick code never really tests
    db $EC, \1
ENDM
MACRO end_track
    db $FF
ENDM
MACRO fx        ; frames/3, value (NRx2, or signed period offset)
    db \1, (\2) & $FF
ENDM
MACRO fx_jump
    db 0
    dw \1
ENDM
MACRO sfx_tone  ; frames, NR10..NR14
    db \1, \2, \3, \4, \5, \6
ENDM
MACRO sfx_noise ; frames, NR42, NR43
    db \1, \2, \3
ENDM
MACRO sfx_count
    db $F0 | (\1)
ENDM
MACRO sfx_loop
    db $EF
    dw \1
ENDM
MACRO sfx_end
    db 0
ENDM

SECTION "Sound", ROMX[$4000], BANK[$0F]

runSoundEngine:
    jr runSoundEngineReal
    db $00

initSoundEngine:
    jr initSoundEngineReal
    db $00

runSoundEngineReal:
    push af
    push bc
    push de
    push hl
    ldh a, [hMusicSpecialSongRequest]
    or a
    jr z, runSoundEngineReal.l401E
    ldh a, [hMusicSpecialSongPlaying]
    or a
    jr z, runSoundEngineReal.l4019
    call musicSpecialSongCheckFinished
    jr runSoundEngineReal.l403D
.l4019:
    call musicSpecialSongStart
    jr runSoundEngineReal.l403D
.l401E:
    ldh a, [hMusicSpecialSongPlaying]
    or a
    jr z, runSoundEngineReal.l4028
    call musicSpecialSongResumeSavedSong
    jr runSoundEngineReal.l403D
.l4028:
    ld a, [wSoundEffectDurationChannel1]
    or a
    jr nz, runSoundEngineReal.l4037
    ldh a, [hPlayingMusic]
    ld b, a
    ldh a, [hCurrentMusic]
    cp b
    call nz, musicSongInit
.l4037:
    ldh a, [hSFX]
    or a
    call nz, soundEffectPlay
.l403D:
    call musicPlayStep
    call soundEffectPlayStep
    pop hl
    pop de
    pop bc
    pop af
    ret

initSoundEngineReal:
    ld a, $FF
    ldh [rNR52], a
    call musicInitChannels
    ld a, $FF
    ld [wMusicEndedOnChannel2], a
    ld [wMusicEndedOnChannel1], a
    ld [wMusicEndedOnChannel3], a
    ld [wMusicEndedOnChannel4], a
    ld a, $10
    ldh [rNR12], a
    ldh [rNR22], a
    ldh [rNR32], a
    ldh [rNR42], a
    call muteSoundEngine
    xor a
    ld [wSoundEffectDurationChannel1], a
    ld a, $77
    ldh [rNR50], a
    ld a, $FF
    ldh [rNR51], a
    ld hl, hCurrentMusic
    ld c, $10
    xor a
.l407C:
    ld [hli], a
    dec c
    jr nz, initSoundEngineReal.l407C
    ld [wMusicBrokenDoubleTimeMode], a
    ret

musicInitChannels:
    ld hl, wMusicTempoTimeCounter
    ld a, $FF
    ld [hli], a
    ld a, $3C
    ld [hli], a
    ld b, $03
.l408F:
    ld de, musicChannelInitData
    ld c, $18
.l4094:
    ld a, [de]
    ld [hli], a
    inc e
    dec c
    jr nz, musicInitChannels.l4094
    dec b
    jr nz, musicInitChannels.l408F
    ret

musicSongInit:
    ldh [hPlayingMusic], a
    or a
    jr nz, musicSongPlay
    call initSoundEngineReal
    ret

musicSongPlay:
    push af
    call musicInitChannels
    pop af
    dec a
    ld e, a
    add a, a
    add a, e
    add a, a
    ld hl, musicSongChannelPointers
    ld e, a
    ld d, $00
    add hl, de
    ld a, [hli]
    ld [wMusicInstructionPointerChannel2], a
    ld a, [hli]
    ld [wMusicInstructionPointerChannel2_hi], a
    ld a, [hli]
    ld [wMusicInstructionPointerChannel1], a
    ld a, [hli]
    ld [wMusicInstructionPointerChannel1_hi], a
    ld a, [hli]
    ld [wMusicInstructionPointerChannel3], a
    ld a, [hli]
    ld [wMusicInstructionPointerChannel3_hi], a
    ret

muteSoundEngine:
    xor a
    ldh [rNR10], a
    ld a, $FF
    ldh [rNR13], a
    ldh [rNR23], a
    ldh [rNR31], a
    ldh [rNR33], a
    ld a, $07
    ldh [rNR14], a
    ldh [rNR24], a
    ldh [rNR34], a
    xor a
    ldh [rNR42], a
    ld a, $80
    ldh [rNR44], a
    ret

musicSpecialSongStart:
    call muteSoundEngine
    xor a
    ld [wSoundEffectDurationChannel1], a
    ld [wSoundEffectDurationChannel4], a
    ld c, $62
    ld hl, wMusicTempoTimeCounter
    ld de, $C162
.l4100:
    ld a, [hli]
    ld [de], a
    inc e
    dec c
    jr nz, musicSpecialSongStart.l4100
    ldh a, [hMusicSpecialSongRequest]
    call musicSongPlay
    ld a, $01
    ldh [hMusicSpecialSongPlaying], a
    ret

musicSpecialSongCheckFinished:
    ld a, [wMusicEndedOnChannel2]
    ld e, a
    ld a, [wMusicEndedOnChannel1]
    ld d, a
    ld a, [wMusicEndedOnChannel3]
    and d
    and e
    cp $FF
    ret nz

musicSpecialSongResumeSavedSong:
    call muteSoundEngine
    ld c, $62
    ld hl, wMusicTempoTimeCounter
    ld de, $C162
.l412B:
    ld a, [de]
    ld [hli], a
    inc e
    dec c
    jr nz, musicSpecialSongResumeSavedSong.l412B
    xor a
    ldh [hMusicSpecialSongRequest], a
    ldh [hMusicSpecialSongPlaying], a
    ld a, [wMusicNR21DutyCycleChannel2]
    ldh [rNR21], a
    ld a, [wMusicNR22DefaultVolumeChannel2]
    ldh [rNR22], a
    ld a, $87
    ldh [rNR24], a
    ldh a, [hWaveTablePointer]
    ld l, a
    ldh a, [hWaveTablePointer_hi]
    ld h, a
    call musicLoadWaveTable

soundEffectRestoreChannel1:
    xor a
    ldh [rNR10], a
    ld a, [wMusicNR11DutyCycleChannel1]
    ldh [rNR11], a
    ld a, [wMusicNR12DefaultVolumeChannel1]
    ldh [rNR12], a
    ld a, [wSoundsMusicRestorePitchChannel1]
    ldh [rNR13], a
    ld a, [wSoundsMusicRestorePitchChannel1_hi]
    ldh [rNR14], a
    ld a, [wMusicStereoPanChannel1]
    ld e, a
    ldh a, [rNR51]
    and $EE
    or e
    ldh [rNR51], a
    ret

soundEffectMuteChannel4:
    xor a
    ldh [rNR42], a
    ldh [rNR43], a
    ld a, $80
    ldh [rNR44], a
    ret

musicChannelInitData:
    db $00, $01 ; +0 sfx timer, +1 note timer
    dw $0000       ; +2 stream pointer
    db $14        ; +4 pitch fx timer
    dw DefaultPitchFx, DefaultPitchFx
    db $60, $00, $00, $00, $00, $10, $0F, $00, $00 ; +9..+$11 (+$11 = ended flag)
    db $01        ; +$12 volume fx timer
    dw DefaultVolumeFx, DefaultVolumeFx
    db $00        ; +$17 loop counter B

DefaultPitchFx:
    fx $0A, $00
.l4194:
    fx $02, $01
    fx $02, $00
    fx_jump DefaultPitchFx.l4194

DefaultVolumeFx:
    fx $FF, $F0
    fx_jump DefaultVolumeFx

musicNoteFrequencies:
    ; period | $8000 (trigger); index = octave*24 + pitch*2
    dw $802C, $809D, $8107, $816B, $81C9, $8223, $8277, $82C7, $8312, $8358, $839B, $83DA
    dw $8416, $844E, $8483, $84B5, $84E5, $8511, $853B, $8563, $8589, $85AC, $85CE, $85ED
    dw $860B, $8627, $8642, $865B, $8672, $8689, $869E, $86B2, $86C4, $86D6, $86E7, $86F7
    dw $8706, $8714, $8721, $872D, $8739, $8744, $874F, $8759, $8762, $876B, $8773, $877B
    dw $8783, $878A, $8790, $8797, $879D, $87A2, $87A7, $87AC, $87B1, $87B6, $87BA, $87BE
    dw $87C1, $87C5, $87C8, $87CB, $87CE, $87D1, $87D4, $87D6, $87D9, $87DB, $87DD, $87DF
    dw $87E1, $87E2, $87E4, $87E6, $87E7, $87E9, $87EA, $87EB, $87EC, $87ED, $87EE, $87EF
    dw $87F0

musicNoteDurations:
    db $60, $48, $30, $20, $24, $18, $10, $12, $0C, $08, $06, $04, $03

musicPlayStep:
    ld a, [wMusicTempoTimeCounter]
    ld b, a
    ld a, [wMusicTempo]
    add a, b
    ld [wMusicTempoTimeCounter], a
    jr nc, musicPlayStep.l426E
    call musicTempoPlayNotes
    ld a, [wMusicBrokenDoubleTimeMode]
    or a
    call musicTempoPlayNotes
.l426E:
    ldh a, [hVibratoVolumeChannelSelection]
    inc a
    cp $03
    jr nz, musicPlayStep.l4276
    xor a
.l4276:
    ldh [hVibratoVolumeChannelSelection], a
    or a
    call z, musicVibratoAndVolumeChannel2
    ldh a, [hVibratoVolumeChannelSelection]
    cp $01
    call z, musicVibratoAndVolumeChannel1
    ldh a, [hVibratoVolumeChannelSelection]
    cp $02
    call z, musicVibratoAndVolumeChannel3
    ret

musicTempoPlayNotes:
    ld a, [wMusicEndedOnChannel2]
    cp $FF
    jp z, musicTempoPlayNotes_Channel1
    ld a, [wMusicNoteDurationChannel2]
    dec a
    ld [wMusicNoteDurationChannel2], a
    ldh [hMusicNoteDurationChannel2Copy], a
    jp nz, musicTempoPlayNotes_Channel1
.l429F:
    call getNextMusicInstructionChannel2
    ld e, a
    cp $D0
    jr nc, musicTempoPlayNotes.l4311
    and $F0
    swap a
    ld c, a
    ld hl, musicNoteDurations
    ld b, $00
    add hl, bc
    ld a, [hl]
    ld [wMusicNoteDurationChannel2], a
    ld a, e
    and $0F
    ld [wMusicNotePitchChannel2], a
    cp $0E
    jp z, musicTempoPlayNotes_Channel1
    cp $0F
    jr nz, musicTempoPlayNotes.l42D0
    ld a, $FF
    ldh [rNR23], a
    ld a, $07
    ldh [rNR24], a
    jp musicTempoPlayNotes_Channel1
.l42D0:
    add a, a
    ld e, a
    ld a, [wMusicOctaveChannel2]
    add a, e
    ld e, a
    ld d, $00
    ld hl, musicNoteFrequencies
    add hl, de
    push hl
    ld a, [wMusicVolumeEnvelopeChannel2]
    ld l, a
    ld a, [wMusicVolumeEnvelopeChannel2_hi]
    ld h, a
    ld a, [hli]
    ld [wMusicVolumeDurationChannel2], a
    ld a, [hli]
    ldh [rNR22], a
    ld a, l
    ld a, [wMusicVolumeEnvelopePointerChannel2]
    ld a, h
    ld a, [wMusicVolumeEnvelopePointerChannel2_hi]
    pop hl
    ld a, [hli]
    ldh [rNR23], a
    ld [wMusicCurrentPitchChannel2], a
    ld a, [hl]
    ldh [rNR24], a
    ld [wMusicCurrentPitchChannel2_hi], a
    ld hl, wMusicVibratoDurationChannel2
    call musicStartEnvelope
    ld hl, wMusicVolumeDurationChannel2
    call musicStartEnvelope
    jp musicTempoPlayNotes_Channel1
.l4311:
    cp $FF
    jr nz, musicTempoPlayNotes.l4321
    ld [wMusicEndedOnChannel2], a
    ldh [rNR23], a
    ld a, $07
    ldh [rNR24], a
    jp musicTempoPlayNotes_Channel1
.l4321:
    cp $E0
    jr nc, musicTempoPlayNotes.l434B
    bit 3, a
    jr nz, musicTempoPlayNotes.l4337
    and $07
    add a, a
    add a, a
    add a, a
    ld e, a
    add a, a
    add a, e
    ld [wMusicOctaveChannel2], a
    jp musicTempoPlayNotes.l429F
.l4337:
    and $07
    ld e, a
    ld d, $00
    ld hl, musicOctaveRelatvieOffsets
    add hl, de
    ld e, [hl]
    ld a, [wMusicOctaveChannel2]
    add a, e
    ld [wMusicOctaveChannel2], a
    jp musicTempoPlayNotes.l429F
.l434B:
    and $0F
    add a, a
    ld hl, musicOpCodeTableChannel2
    ld e, a
    ld d, $00
    add hl, de
    call musicCallOpCode
    jp musicTempoPlayNotes.l429F

musicCallOpCode:
    ld a, [hli]
    ld e, a
    ld a, [hl]
    ld h, a
    ld l, e
    jp hl

musicOpCodeHalt:
    jp musicOpCodeHalt
    db $C9

musicOpCodeTableChannel2:
    dw musicOpCodeSetChannel2VolumeEnvelope     ; $E0
    dw musicOpCodeChannel2Jump                  ; $E1
    dw musicOpCodeChannel2LoopCounter1          ; $E2
    dw musicOpCodeSetChannel2LoopCounter1       ; $E3
    dw musicOpCodeSetChannel2VibratoEnvelope    ; $E4
    dw musicChannel2SetDutyCycle                ; $E5
    dw musicOpCodeSetChannel2StereoPan          ; $E6
    dw musicOpCodeSetTempo                      ; $E7
    dw musicOpCodeHalt                          ; $E8  (halt)
    dw musicOpCodeChannel2LoopCounter2          ; $E9
    dw musicOpCodeSetChannel2LoopCounter2       ; $EA
    dw musicOpCodeIfChannel2LoopCounter1Equal   ; $EB
    dw musicOpCodeSetDoubletimeMode             ; $EC

musicOpCodeSetDoubletimeMode:
    call getNextMusicInstructionChannel2
    ld [wMusicBrokenDoubleTimeMode], a
    ret

musicOpCodeSetChannel2VolumeEnvelope:
    ld hl, wMusicInstructionPointerChannel2
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, [de]
    ld c, a
    inc de
    ld a, [de]
    inc de
    ld [wMusicVolumeEnvelopeChannel2_hi], a
    ld [wMusicVolumeEnvelopePointerChannel2_hi], a
    ld a, c
    ld [wMusicVolumeEnvelopeChannel2], a
    ld [wMusicVolumeEnvelopePointerChannel2], a
    ld a, e
    ld [wMusicInstructionPointerChannel2], a
    ld a, d
    ld [wMusicInstructionPointerChannel2_hi], a
    ret

musicOpCodeChannel2Jump:
    ld hl, wMusicInstructionPointerChannel2
    ld e, [hl]
    inc hl
    ld d, [hl]
    ld a, [de]
    inc de
    ld [wMusicInstructionPointerChannel2], a
    ld a, [de]
    ld [wMusicInstructionPointerChannel2_hi], a
    ret

musicOpCodeChannel2LoopCounter1:
    ld hl, wMusicInstructionPointerChannel2
    call musicGetLoopTarget
    ld b, a
    ld a, [wMusicLoopCounter1Channel2]
    dec a
    ld [wMusicLoopCounter1Channel2], a
    jr jumpIfCondition

musicOpCodeChannel1LoopCounter1:
    ld hl, wMusicInstructionPointerChannel1
    call musicGetLoopTarget
    ld b, a
    ld a, [wMusicLoopCounter1Channel1]
    dec a
    ld [wMusicLoopCounter1Channel1], a
    jr jumpIfCondition

musicOpCodeChannel3LoopCounter1:
    ld hl, wMusicInstructionPointerChannel3
    call musicGetLoopTarget
    ld b, a
    ld a, [wMusicLoopCounter1Channel3]
    dec a
    ld [wMusicLoopCounter1Channel3], a
    jr jumpIfCondition

musicOpCodeChannel2LoopCounter2:
    ld hl, wMusicInstructionPointerChannel2
    call musicGetLoopTarget
    ld b, a
    ld a, [wMusicLoopCounter2Channel2]
    dec a
