    ld l, e
    ld h, a
    ld a, [hli]
    ret

soundEffectPlay:
    dec a
    add a, a
    ld e, a
    ld d, $00
    ld hl, soundEffectDataChannel1
    add hl, de
    ld a, [hli]
    ld [wSoundEffectInstructionPointerChannel1], a
    ld a, [hl]
    ld [wSoundEffectInstructionPointerChannel1_hi], a
    ld hl, soundEffectDataChannel4
    add hl, de
    ld a, [hli]
    ld [wSoundEffectInstructionPointerChannel4], a
    ld a, [hli]
    ld [wSoundEffectInstructionPointerChannel4_hi], a
    ld a, $01
    ld [wSoundEffectDurationChannel1], a
    ld [wSoundEffectDurationChannel4], a
    xor a
    ldh [hSFX], a
    ret

soundEffectPlayStep:
    ld a, [wSoundEffectDurationChannel1]
    or a
    jp z, soundEffectPlayStep.l49BC
    dec a
    ld [wSoundEffectDurationChannel1], a
    or a
    jr nz, soundEffectPlayStep.l49BC
    ld a, [wSoundEffectInstructionPointerChannel1]
    ld l, a
    ld a, [wSoundEffectInstructionPointerChannel1_hi]
    ld h, a
.l497B:
    ld a, [hli]
    ld [wSoundEffectDurationChannel1], a
    or a
    jr nz, soundEffectPlayStep.l4987
